# Drawplate installer - generated by scripts/build-installers.ps1
# Modules: 00-header 10-ui 20-platform 30-net 40-verify 50-install 60-path 70-setup-offer 80-uninstall 90-main
# ASCII only, compatible with Windows PowerShell 5.1 and PowerShell 7+

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$version = $env:DRAWPLATE_VERSION
$installDir = $env:DRAWPLATE_INSTALL_DIR
$repo = $env:DRAWPLATE_REPO
if (-not $repo) { $repo = 'migueljocode/Drawplate' }
$baseUrl = $env:DRAWPLATE_BASE_URL
if (-not $baseUrl) { $baseUrl = "https://github.com/$repo/releases" }
$fromArchive = $env:DRAWPLATE_FROM_ARCHIVE
$fromSha256 = $env:DRAWPLATE_SHA256
$noSetup = [bool]::Parse($env:DRAWPLATE_NO_SETUP)
$yes = [bool]::Parse($env:DRAWPLATE_YES)
$uninstall = [bool]::Parse($env:DRAWPLATE_UNINSTALL)

function Usage {
    Write-Error "Usage: install.ps1 [-Version <tag>] [-Dir <folder>] [-NoSetup] [-Yes] [-Uninstall] [-From <archive> -Sha256 <hash>] [-Help]"
    exit 10
}

function Err([string]$text, [string]$hint, [int]$code) {
    Write-Error ("Error: " + $text)
    Write-Error ("Hint: " + $hint)
    exit $code
}

if ($fromArchive -and -not $fromSha256) { Err "--sha256 is required with --from" "Provide the archive SHA-256 hash." 10 }

# Detect platform
$isWindows = [Environment]::OSVersion.Platform -eq 'Win32NT'
if (-not $isWindows) { Err "Unsupported platform: $(uname -s) $(uname -m)" "Supported: linux-x64, linux-arm64, osx-arm64, win-x64." 11 }
$arch = [Environment]::Is64BitOperatingSystem
$rid = 'win-x64'

# Resolve tag
if (-not $version) {
    try {
        $wc = New-Object System.Net.WebClient
        $resp = $wc.DownloadString("$baseUrl/latest")
        $version = $resp.Trim()
    } catch { $version = '' }
}
if (-not $version) { Err "Could not find a release for $repo" "Check your internet connection, or set DRAWPLATE_VERSION." 12 }
$tag = $version
$pkgVersion = $tag.TrimStart('v')
$archive = "drawplate-$pkgVersion-$rid.zip"
$url = "$baseUrl/download/$tag/$archive"

# Locations
$binDir = $installDir
if (-not $binDir) { $binDir = Join-Path $env:LOCALAPPDATA 'Programs\Drawplate' }
$dataDir = Join-Path $env:LOCALAPPDATA 'Drawplate'
$binary = Join-Path $binDir 'drawplate.exe'
$manifest = Join-Path $dataDir 'install.json'

# Lock
$lockDir = Join-Path $dataDir '.lock'
if (Test-Path $lockDir) {
    $lockAge = (Get-Date) - (Get-Item $lockDir).LastWriteTime
    if ($lockAge.TotalMinutes -lt 30) {
        Err "Another installation is running (lock: $lockDir)." "Wait for it, or delete that folder if no installer is running." 15
    }
    Remove-Item $lockDir -Recurse -Force
}
New-Item -ItemType Directory -Path $lockDir -Force | Out-Null

try {
    # Up-to-date check
    if (Test-Path $manifest -and Test-Path $binary) {
        $manifestJson = Get-Content $manifest -Raw | ConvertFrom-Json
        $manifestVersion = $manifestJson.version
        $binaryHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $binary).Hash.ToLower()
        $manifestHash = $manifestJson.binarySha256.ToLower()
        $binVersion = & "$binary" --version 2>$null | ForEach-Object { $_ -replace 'drawplate ', '' }
        if ($manifestVersion -eq $pkgVersion -and $binaryHash -eq $manifestHash -and $binVersion -eq $pkgVersion) {
            Write-Host "[1/8] Detecting platform ..... [ok] $rid"
            Write-Host "[2/8] Finding release ........ [ok] $tag"
            Write-Host "[3/8] Downloading Drawplate .... [skipped] up to date"
            Write-Host "[4/8] Downloading checksums .... [skipped] up to date"
            Write-Host "[5/8] Verifying checksum ....... [skipped] up to date"
            Write-Host "[6/8] Installing ............. [skipped] up to date"
            Write-Host "[7/8] Checking the install .... [skipped] up to date"
            Write-Host "[8/8] Finishing .............. [ok] done"
            Write-Host ""
            Write-Host ("Installed Drawplate $pkgVersion to $binary")
            Write-Host "Next:"
            Write-Host "  drawplate --help"
            Write-Host "  drawplate setup        (shows how to install FFmpeg)"
            $currentPath = [Environment]::GetEnvironmentVariable('Path', 'User')
            $paths = $currentPath -split ';' | Where-Object { $_ -ne '' }
            $found = $false
            foreach ($p in $paths) { if ($p.TrimEnd('\').TrimEnd('/') -eq $binDir.TrimEnd('\').TrimEnd('/')) { $found = $true } }
            if (-not $found) {
                Write-Host ("Note: $binDir is not on your PATH.")
                Write-Host "Your user PATH was updated. Open a new terminal to use 'drawplate'."
            }
            if (-not (Get-Command ffmpeg -ErrorAction SilentlyContinue) -and -not $noSetup -and -not $yes) {
                Write-Host "FFmpeg was not found on this machine."
                Write "Run 'drawplate setup' now? [Y/n] "
                $ans = Read-Host
                if ($ans -eq 'n' -or $ans -eq 'N') { } else { drawplate setup 2>$null || {} }
            } elseif ($yes) {
                drawplate setup 2>$null || {}
            }
            exit 0
        }
    }

    Write-Host "[1/8] Detecting platform ..... [ok] $rid"
    Write-Host "[2/8] Finding release ........ [ok] $tag"

    # Download
    New-Item -ItemType Directory -Path $binDir -Force | Out-Null
    $staging = Join-Path $binDir ('.drawplate-staging-' + [System.IO.Path]::GetRandomFileName())
    New-Item -ItemType Directory -Path $staging -Force | Out-Null
    $archivePath = Join-Path $staging $archive
    if ($fromArchive) {
        Copy-Item -Path $fromArchive -Destination $archivePath
        $actualHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $archivePath).Hash.ToLower()
        if ($actualHash -ne $fromSha256.ToLower()) { Err "Checksum mismatch for $archive." "Nothing was installed. Retry." 13 }
    } else {
        Write-Host "[3/8] Downloading Drawplate ...."
        $wc = New-Object System.Net.WebClient
        $wc.DownloadFile($url, $archivePath)
        Write-Host "      [####################] 100%  done"
    }

    # Checksums
    $sumsUrl = "$baseUrl/download/$tag/SHA256SUMS"
    $sumsFile = Join-Path $staging 'SHA256SUMS'
    $wc2 = New-Object System.Net.WebClient
    $wc2.DownloadFile($sumsUrl, $sumsFile)
    $expected = (Select-String -Pattern $archive -Path $sumsFile).Line.Split(' ')[0]
    $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $archivePath).Hash.ToLower()
    if ($expected -ne $actual) { Err "Checksum mismatch for $archive." "Nothing was installed. Retry." 13 }
    Write-Host "[4/8] Downloading checksums .... [ok] done"
    Write-Host "[5/8] Verifying checksum ....... [ok] done"

    # Install
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $extractDir = Join-Path $staging 'x'
    [System.IO.Compression.ZipFile]::ExtractToDirectory($archivePath, $extractDir)
    $exe = Join-Path $extractDir 'drawplate.exe'
    if (-not (Test-Path $exe)) { Err "Could not install to $binDir" "Choose another folder with DRAWPLATE_INSTALL_DIR." 5 }
    if (Test-Path $binary) { Move-Item -Path $binary -Destination ("$binary.old") -Force }
    Move-Item -Path $exe -Destination $binary -Force
    $check = & "$binary" --version 2>$null
    if (-not $check) {
        if (Test-Path "$binary.old") { Move-Item -Path "$binary.old" -Destination $binary -Force }
        Err "The installed program did not start." "The previous version was restored." 14
    }
    if (Test-Path "$binary.old") { Remove-Item "$binary.old" -Force }

    # Manifest
    $installedAt = Get-Date -Format 'yyyy-MM-ddTHH:mm:ssZ'
    $binHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $binary).Hash.ToLower()
    $archHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $archivePath).Hash.ToLower()
    New-Item -ItemType Directory -Path $dataDir -Force | Out-Null
    $manifestJson = '{"version":"' + $pkgVersion + '","rid":"' + $rid + '","archiveSha256":"' + $archHash + '","binarySha256":"' + $binHash + '","installedAt":"' + $installedAt + '","path":"' + $binary + '"}'
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($manifest, $manifestJson, $utf8)

    Write-Host "[6/8] Installing ............. [ok] done"
    Write-Host "[7/8] Checking the install .... [ok] done"
    Write-Host "[8/8] Finishing .............. [ok] done"
    Write-Host ""
    Write-Host ("Installed Drawplate $pkgVersion to $binary")
    Write-Host "Next:"
    Write-Host "  drawplate --help"
    Write-Host "  drawplate setup        (shows how to install FFmpeg)"
    $currentPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    $paths = $currentPath -split ';' | Where-Object { $_ -ne '' }
    $found = $false
    foreach ($p in $paths) { if ($p.TrimEnd('\').TrimEnd('/') -eq $binDir.TrimEnd('\').TrimEnd('/')) { $found = $true } }
    if (-not $found) {
        $newPath = $currentPath + ';' + $binDir
        [Environment]::SetEnvironmentVariable('Path', $newPath, 'User')
        [Environment]::SetEnvironmentVariable('Path', $newPath, 'Process')
        Write-Host ("Your user PATH was updated. Open a new terminal to use 'drawplate'.")
    }
    if (-not (Get-Command ffmpeg -ErrorAction SilentlyContinue) -and -not $noSetup -and -not $yes) {
        Write-Host "FFmpeg was not found on this machine."
        Write "Run 'drawplate setup' now? [Y/n] "
        $ans = Read-Host
        if ($ans -eq 'n' -or $ans -eq 'N') { } else { drawplate setup 2>$null || {} }
    } elseif ($yes) {
        drawplate setup 2>$null || {}
    }

    exit 0
}
finally {
    Remove-Item $lockDir -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item $staging -Recurse -Force -ErrorAction SilentlyContinue
}
